-- database-schema.md §13.2: creation_hash is immutable once the row exists (SOC-01).
CREATE FUNCTION "social_reject_creation_hash_change"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'creation_hash is immutable on %', TG_TABLE_NAME USING ERRCODE = 'check_violation';
END;
$$;--> statement-breakpoint
